// Identifies when a full byte has been received, and validates the stop bit.
// Synchronous reset is active-high.
module TopModule (
  input  clk,
  input  reset,
  input  in,
  output done
);
  reg [2:0] state;
  reg [7:0] data;
  reg       done_reg;
  wire      done_next = (state == 3) && in;
  wire      load_data = (state == 1) && in;
  wire      next_state = state[2] & ~(state[1] & state[0]) | load_data;
  always @(posedge clk) begin
    if (reset) begin
      state <= 3'b000;
      data <= 8'd0;
      done_reg <= 1'b0;
    end else begin
      state <= {next_state, state[2:1]};
      if (load_data) data <= {in, data[7:1]};
      done_reg <= done_next;
    end
  end
  assign done = done_reg;
endmodule

